theorem hermitian_square_frobenius_pair {A B : Matrix I I ℝ}
    (hA : A.IsHermitian) (hB : B.IsHermitian) :
    (∑ i, ∑ j, (A*A) i j * (B*B) i j) = ∑ i, ∑ j, ((A*B) i j)^2

theorem integral_mem_derivative_domain {z : TimeProbabilityL2 × ProductDerivativeL2}
    (hz : z ∈ completedGraph) :
    itoIntegral ⟨z.1, completedGraph_predictable hz⟩ ∈ closedCylindricalDerivative.domain

theorem gradient_truncation_norm_le {f : GaussianL2} {g : GaussianVectorL2}
    (hf : (f, g) ∈ closedCylindricalDerivative.graph) (N : ℕ) :
    ‖gradientTruncation N f‖ ≤ ‖g‖

theorem independent_graph_mem_completed {u : TimeProbabilityL2} {v : ProductDerivativeL2}
    (hu : u ∈ fullPredictable) (hd : (u, v) ∈ derivative.graph) :
    (u, v) ∈ completedGraph

theorem IsDivergenceMultiplier.add {f g : Ω → ℝ}
    (hf : IsDivergenceMultiplier δ f) (hg : IsDivergenceMultiplier δ g) :
    IsDivergenceMultiplier δ (f + g)

theorem IsDivergenceMultiplier.mul {f g : Ω → ℝ}
    (hf : IsDivergenceMultiplier δ f) (hg : IsDivergenceMultiplier δ g) :
    IsDivergenceMultiplier δ (f * g)
